#include <iostream>
#include <cstdint>

int main() {
  int i = 10;
  // Correct way to cast an integer to a void pointer and back:
  void* pv = reinterpret_cast<void*>(&i); // reinterpret_cast for low-level reinterpreting
  int* pi = reinterpret_cast<int*>(pv);  // reinterpret_cast for low-level reinterpreting
  std::cout << *pi << std::endl; // Output: 10

  // Incorrect and dangerous example (avoid):
  // double* pd = (double*)pv;  // C-style cast - Avoid this!
  // This might compile but leads to undefined behavior because the sizes are different

  // safer example with static_cast if the types are compatible:
  std::uint64_t large_int = 10000000000; // a 64 bit integer
  void* pv2 = &large_int;
  std::uint32_t* small_int_ptr = static_cast<std::uint32_t*>(pv2); //potentionally dangerous but shows how to use static_cast. Note that there might be a loss of data
  std::cout << *small_int_ptr << std::endl; //Output: A truncated value, undefined behavior in strict sense
  return 0;
}
